-- Essential Services
local HttpService = game:GetService("HttpService")

-- Configuration
local keyFile = "somanyfuckingniggers1.txt"
local keyDuration = 86400 -- 24 hours
local HubUrl = "https://gist.githubusercontent.com/whoisnwr/94a521adaaa5296b8ef5f2c99e5f8e56/raw/d6c2103183381f5a52fea3cecffc9a63f14e1c1c/gistfile1.txt"

-- // KEY DATABASE (Updated from generated_keys.json)
local KeyPool = {
    -- Premium Key
    ["43737689431abafb7d26015a4"] = "Premium",
    
    -- Standard Keys (NWR's Hub Keys V1)
    ["fe4323c2-0885-4345-ab65-fcfc705a0f91"] = "Standard", ["0ba7c5d0-7758-4167-b281-cc1607163400"] = "Standard",
}

-- Load Fluent UI
local Success, Library = pcall(function()
    return loadstring(game:HttpGet("https://github.com/ActualMasterOogway/Fluent-Renewed/releases/latest/download/Fluent.luau"))()
end)
if not Success or not Library then return end

local function loadHub(tier)
    Library:Notify({ Title = "Success", Content = "Loading " .. tier .. " Hub...", Duration = 3 })
    task.spawn(function()
        pcall(function() loadstring(game:HttpGet(HubUrl))() end)
    end)
end

-- UI Setup
local Window = Library:Window({
    Title = "NWR's Hub",
    SubTitle = "Security Check",
    TabWidth = 160, Size = UDim2.fromOffset(580, 460),
    Acrylic = true, Theme = "Darker",
})

local Tab = Window:AddTab({ Title = "Verify", Icon = "key" })
local Section = Tab:Section("Key System")
local KeyInput = Section:Input("KeyInput", { Title = "Enter Key", Placeholder = "Enter your key here..." })

Section:Button({
    Title = "Check Key",
    Callback = function()
        local input = KeyInput.Value
        local tier = KeyPool[input] 
        
        if tier then
            writefile(keyFile, input .. "\n" .. tostring(os.time()))
            Library:Notify({ Title = "Access Granted", Content = tier .. " key accepted.", Duration = 3 })
            task.wait(0.5)
            Window:Destroy()
            loadHub(tier)
        else
            Library:Notify({ Title = "Error", Content = "Invalid Key!", Duration = 3 })
        end
    end
})

Section:Button({
    Title = "Get Key ",
    Callback = function()
        -- Update this link with your actual key-getting link
        setclipboard("https://discord.gg/cmq6hjxAhq")
        Library:Notify({ Title = "Copied", Content = "Link added to clipboard.", Duration = 3 })
    end
})

-- Auto-Login Logic (checks if the saved key is still valid and in our pool)
if isfile(keyFile) then
    local data = readfile(keyFile)
    local key, time = data:match("^(.-)\n(.-)$")
    if key and KeyPool[key] and (os.time() - (tonumber(time) or 0)) < keyDuration then
        loadHub(KeyPool[key])
        Window:Destroy()
    end
end

